package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.config.ResultApplicationFactory;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.JobsService.*;
import org.junit.jupiter.api.*;

/** Real external confirmation and real manual report handler with native current content proof. */
class ConfirmedContentApplicationTest extends ManualResultFactoryTest {
    @Override @BeforeEach void setup(){
        f=fixture();f.jdbc.execute("ALTER TABLE article_revisions ADD article_id VARCHAR(64)");f.jdbc.execute("DROP TABLE IF EXISTS articles");f.jdbc.execute("CREATE TABLE articles(id VARCHAR(64) PRIMARY KEY)");f.jdbc.update("INSERT INTO articles VALUES('fictional-article')");f.jdbc.update("UPDATE article_revisions SET article_id='fictional-article'");f.jdbc.execute("ALTER TABLE article_revisions ADD validity_revision BIGINT NOT NULL DEFAULT 0");f.jdbc.execute("ALTER TABLE jobs ADD validity_revision BIGINT");f.jdbc.execute("ALTER TABLE jobs ADD reverses_disposition_id VARCHAR(64)");f.jdbc.execute("ALTER TABLE jobs ADD error_code VARCHAR(64)");factory=new ResultApplicationFactory(f.source,f.tx,f.clock);f.existingContent();
        new TransportUnknownService(f.writes,new JdbcTransportUnknown(f.source),f.clock,"fictional-epoch").release(f.identity,TransportUnknownService.Cause.TRANSPORT_UNKNOWN,f.action("fictional-confirmed-unknown"));var raw=CanonicalJson.parse(f.raw());var root=new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT);var command=new JobAction(root.revision(),"resolve_external","Fictional verified original result",f.identity.attemptId(),null,null,"succeeded",java.util.List.of("fictional-external-evidence"),new ValidatedResult("1",f.identity.inputHash(),raw.get("payload"),raw.get("result_hash").textValue()),null);assertTrue(new OwnerJobResolveExternalService(f.source,f.tx,f.writes,f.clock).resolve(owner,ResultJdbcStoreTest.ROOT,command,"fictional-confirmed-original").rootResultRetained());
    }
    void invalidateReference(){
        var source=f.source;var clock=f.clock;
        var generated=new com.lianxibu.site.service.content.GeneratedContentService(new com.lianxibu.site.repository.content.JdbcGeneratedContents(source),clock);
        var ledger=new VersionValidityLedgerService(new JdbcVersionValidity(source),new FrozenContentVersionService(new JdbcFrozenContentVersions(source)),new com.lianxibu.site.service.articles.EvidenceValidityService(new com.lianxibu.site.repository.articles.JdbcEvidenceValidity(source)),new com.lianxibu.site.service.content.ContentReviewWriteService(new com.lianxibu.site.repository.content.JdbcReviewPublication(source),generated,clock),clock,"fictional-owner");
        var target=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("kind","article_revision").put("id","fictional-citation");var command=new VersionValidityService.Command(target,0,VersionValidityService.Action.INVALIDATE,"Fictional native reference invalidation",null);
        f.writes.execute(f.action("fictional-confirmed-native-invalidation"),key->null,c->{ledger.lockStableIdentity(target);String id=ledger.append(command,VersionValidityService.commandHash(command,VersionValidityService.canonicalTarget(target)),1,c.actionKey());assertFalse(ledger.validity(target).effectiveValid());return id;});
    }
    @Test void ConfirmedMaterialWaitsForSeparateExplicitOwnerApplication(){assertEquals("EXTERNAL_RESULT_CONFIRMED",new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).application());assertEquals(1,f.jdbc.queryForObject("SELECT revision FROM contents",Long.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='report_result_ready'",Integer.class));long before=revision();var service=new OwnerJobApplyResultService(new JdbcOwnerRetainedResultReads(f.source),f.tx,factory::forManual);var hash=new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).resultHash();var result=service.apply(owner,ResultJdbcStoreTest.ROOT,before,1,hash,"Fictional confirmed application","fictional-confirmed-apply");assertEquals(before+1,result.revision());assertEquals(2,result.contentRevision());assertEquals("APPLIED",new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).application());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='report_result_ready'",Integer.class));}
    @Test void ConfirmedMaterialStillRequiresBothCasAndValidOriginalReferences(){long before=revision();var value=factory.forManual(f.identity,owner);String hash=new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).resultHash();assertEquals(ResultApplicationService.ManualRefusal.REVISION_CONFLICT,assertThrows(ResultApplicationService.ManualRejected.class,()->value.service().applyManual(value.input(),hash,before,2L,"Fictional stale confirmation",true,f.action("fictional-confirmed-stale"))).refusal());invalidateReference();assertEquals(ResultApplicationService.ManualRefusal.INVALID_EVIDENCE,assertThrows(ResultApplicationService.ManualRejected.class,()->apply("fictional-confirmed-invalid-reference",before)).refusal());assertEquals(before,revision());assertEquals(1,f.jdbc.queryForObject("SELECT revision FROM contents",Long.class));}
    @Test void UnrecognizedApplicationStateDoesNotReceiveManualPermission(){long before=revision();f.jdbc.update("UPDATE jobs SET application_state='FICTIONAL_OTHER_STATE' WHERE id=?",ResultJdbcStoreTest.ROOT);assertEquals(ResultApplicationService.ManualRefusal.RUN_FROZEN,assertThrows(ResultApplicationService.ManualRejected.class,()->apply("fictional-unrecognized-state",before)).refusal());assertEquals(before,revision());}
}
